import { describe, expect, it } from '@jest/globals';
import { Severity } from '@hint/utils-types';
import hint from '../../../src/hints/opengraph/opengraph-image-too-large.js';
import { runHint } from '../../helpers/run-hint.js';
import { page } from './page.js';

describe('opengraph-image-too-large', () => {
  it('passes for a small image', async () => {
    expect(
      await runHint(
        hint,
        page('<meta property="og:image" content="/i.svg">', {
          '/i.svg': {
            headers: { 'content-type': 'image/svg+xml' },
            body: '<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630"><!----></svg>',
          },
        }),
      ),
    ).toEqual([]);
  });

  it('passes just under 500 KB', async () => {
    expect(
      await runHint(
        hint,
        page('<meta property="og:image" content="/i.svg">', {
          '/i.svg': {
            headers: { 'content-type': 'image/svg+xml' },
            body: '<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630"><!----></svg>',
          },
        }),
      ),
    ).toEqual([]);
  });

  it('reports an image over 500 KB', async () => {
    const problems = await runHint(
      hint,
      page('<meta property="og:image" content="/i.svg">', {
        '/i.svg': {
          headers: { 'content-type': 'image/svg+xml' },
          body: '<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630"><!----></svg>',
        },
      }),
    );
    expect(problems).toHaveLength(1);
    expect(problems[0].message).toContain('WhatsApp');
    expect(
      problems[0].message.endsWith(
        'https://www.opengraph.to/articles/og-image-too-large',
      ),
    ).toBe(true);
    expect(problems[0].severity).toBe(Severity.warning);
  });

  it('passes without og:image', async () => {
    expect(await runHint(hint, page(''))).toEqual([]);
  });

  it('reports the image URL and carries the og:image tag', async () => {
    const [problem] = await runHint(
      hint,
      page('<meta property="og:image" content="/i.svg">', {
        '/i.svg': {
          status: 200,
          headers: { 'content-type': 'image/svg+xml' },
          body: `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630"><!--${'x'.repeat(600000)}--></svg>`,
        },
      }),
    );
    expect(problem.resource.endsWith('/i.svg')).toBe(true);
    expect(problem.sourceCode).toContain(
      '<meta property="og:image" content="/i.svg">',
    );
    expect(problem.location.line).toBeGreaterThanOrEqual(0);
  });
});
